using System.Text.Json;
using CREMS.Api.Controllers;
using CREMS.Api.Domain.Customers;
using CREMS.Api.Domain.Identity;
using CREMS.Api.Domain.Rentals;
using CREMS.Api.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;
using Fixture=CREMS.Api.Tests.CustomerJourneyRegressionTests.Fixture;
namespace CREMS.Api.Tests;
public sealed class CustomerAdministrationBehaviorTests
{
    private static CancellationToken T=>TestContext.Current.CancellationToken;
    private static JsonElement Json(object? value)=>JsonSerializer.SerializeToElement(value,new JsonSerializerOptions(JsonSerializerDefaults.Web));
    private static async Task<CustomersController> Controller(Fixture f,CustomerLicenceStorageBehaviorTests.EnvironmentFixture env){var(context,_)=await MaintenanceJobsTests.Setup(f.Db);return new(f.Db,new CurrentStaffScope(f.Db),f.Users,new EmailQueue(),env){ControllerContext=context.ControllerContext};}
    [Fact]public async Task Create_edit_and_block_customer_preserve_reference_and_normalize_contacts()
    {await using var f=await Fixture.Create();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var c=await Controller(f,env);var request=new SaveCustomerRequest("IGNORED"," Training Customer "," NEW@EXAMPLE.TEST "," 123 "," Suva "," ID-1 ");var created=Assert.IsType<CustomerResponse>(Assert.IsType<CreatedAtActionResult>((await c.Create(request,T)).Result).Value);Assert.StartsWith("CUS-",created.CustomerNumber);Assert.NotEqual("IGNORED",created.CustomerNumber);Assert.Equal("new@example.test",created.Email);var updated=Assert.IsType<CustomerResponse>(Assert.IsType<OkObjectResult>((await c.Update(created.Id,request with{Name=" Updated customer ",Address=" "},T)).Result).Value);Assert.Equal(created.CustomerNumber,updated.CustomerNumber);Assert.Equal("Updated customer",updated.Name);Assert.Null(updated.Address);Assert.IsType<OkObjectResult>((await c.SetStatus(created.Id,new(false,true),T)).Result);var entity=await f.Db.Customers.FindAsync([created.Id],T);Assert.False(entity!.IsActive);Assert.True(entity.IsBlocked);}
    [Theory][InlineData("verified",false)][InlineData("pending",true)][InlineData("active",true)][InlineData("blocked",false)][InlineData("locked",false)][InlineData("disabled",false)]
    public async Task Customer_filters_and_summary_headers_follow_account_state(string status,bool expected)
    {await using var f=await Fixture.Create();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var c=await Controller(f,env);var response=Assert.IsAssignableFrom<IReadOnlyList<CustomerResponse>>(Assert.IsType<OkObjectResult>((await c.GetAll("Portfolio",status,0,500,T)).Result).Value);Assert.Equal(expected,response.Count==1);Assert.Equal("1",c.Response.Headers["X-Customer-Total"]);Assert.Equal("1",c.Response.Headers["X-Customer-Pending"]);}
    [Theory][InlineData("lock")][InlineData("unlock")][InlineData("verify-email")][InlineData("disable")][InlineData("enable")]
    public async Task Security_actions_persist_the_requested_account_state_and_event(string action)
    {await using var f=await Fixture.Create();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var c=await Controller(f,env);f.User.AccessFailedCount=3;await f.Users.UpdateAsync(f.User);Assert.IsType<NoContentResult>(await c.CustomerSecurityAction(f.Customer.Id,action,T));switch(action){case "lock":Assert.True(f.User.LockoutEnd>DateTimeOffset.UtcNow);Assert.Equal(AccountLifecycleStatus.Locked,f.User.AccountStatus);break;case "unlock":Assert.Null(f.User.LockoutEnd);Assert.Equal(0,f.User.AccessFailedCount);break;case "verify-email":Assert.True(f.User.EmailConfirmed);break;case "disable":Assert.False(f.User.IsActive);Assert.NotNull(f.User.DeactivatedAt);break;case "enable":Assert.True(f.User.IsActive);Assert.Null(f.User.DeactivatedAt);break;}Assert.Contains(await f.Db.SecurityEvents.ToListAsync(T),x=>x.Type==SecurityEventType.AccessChanged&&x.UserId==f.User.Id);Assert.IsType<BadRequestObjectResult>(await c.CustomerSecurityAction(f.Customer.Id,"unsupported",T));}
    [Fact]public async Task Password_reset_queues_one_time_code_and_revocation_ends_all_customer_sessions()
    {await using var f=await Fixture.Create();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var c=await Controller(f,env);Assert.IsType<AcceptedResult>(await c.ResetCustomerPassword(f.Customer.Id,T));var first=await f.Db.PasswordResetOtps.SingleAsync(T);Assert.Null(first.UsedAt);Assert.IsType<AcceptedResult>(await c.ResetCustomerPassword(f.Customer.Id,T));Assert.NotNull(first.UsedAt);Assert.Equal(2,await f.Db.PasswordResetOtps.CountAsync(T));Assert.Contains(await f.Db.OutboundEmails.ToListAsync(T),x=>x.Category=="CustomerPasswordReset"&&x.Recipient==f.Customer.Email);f.Db.UserSessions.Add(new(){UserId=f.User.Id,WindowId="test-window",ExpiresAt=DateTimeOffset.UtcNow.AddMinutes(15)});await f.Db.SaveChangesAsync(T);Assert.IsType<NoContentResult>(await c.RevokeCustomerSessions(f.Customer.Id,T));var session=await f.Db.UserSessions.SingleAsync(T);Assert.Equal("Revoked by administrator",session.EndReason);Assert.NotNull(session.EndedAt);}
    [Fact]public async Task Online_invitation_creates_an_account_and_supersedes_old_activation_codes()
    {await using var f=await Fixture.Create();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var c=await Controller(f,env);var customer=new Customer{CustomerNumber="CUS-TRAIN-2",Name="Invited Customer",Email="invite@example.test"};f.Db.Customers.Add(customer);await f.Db.SaveChangesAsync(T);Assert.IsType<AcceptedResult>(await c.EnableOnlineAccess(customer.Id,T));var account=await f.Users.Users.SingleAsync(x=>x.CustomerId==customer.Id,T);Assert.True(await f.Users.IsInRoleAsync(account,SystemRoles.Customer));Assert.Equal(AccountLifecycleStatus.ActivationPending,account.AccountStatus);var first=await f.Db.CustomerAccountActivations.SingleAsync(T);Assert.IsType<AcceptedResult>(await c.EnableOnlineAccess(customer.Id,T));Assert.NotNull(first.UsedAt);Assert.Equal(2,await f.Db.CustomerAccountActivations.CountAsync(T));account.EmailConfirmed=true;await f.Users.UpdateAsync(account);Assert.IsType<ConflictObjectResult>(await c.EnableOnlineAccess(customer.Id,T));}
    [Fact]public async Task Activity_search_pagination_and_missing_references_are_consistent()
    {await using var f=await Fixture.Create();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var c=await Controller(f,env);var booking=f.Booking(f.Customer.Id);booking.BookingNumber="ACTIVITY-BOOKING";f.Db.Bookings.Add(booking);await f.Db.SaveChangesAsync(T);var activity=Json(Assert.IsType<OkObjectResult>(await c.Activity(f.Customer.Id,"ACTIVITY",0,999,T)).Value);Assert.Equal(1,activity.GetProperty("summary").GetProperty("bookings").GetInt32());Assert.Equal(10,activity.GetProperty("pagination").GetProperty("pageSize").GetInt32());Assert.Equal(booking.Id,activity.GetProperty("bookings")[0].GetProperty("id").GetGuid());var missing=Guid.NewGuid();Assert.IsType<NotFoundResult>(await c.Activity(missing,null,1,10,T));Assert.IsType<NotFoundResult>((await c.Update(missing,new(null,"Test",null,null,null,null),T)).Result);Assert.IsType<NotFoundResult>(await c.EnableOnlineAccess(missing,T));Assert.IsType<NotFoundResult>(await c.CustomerSecurityAction(missing,"unlock",T));}
}
